#!/usr/bin/env bash
# env.sh — capture Erlang build env into config.mk
# Run this OUTSIDE of bear, e.g.:   ./env.sh && bear -- make

set -euo pipefail

ERTS_VSN=$(erl -noshell -eval \
    'io:format("~s", [erlang:system_info(version)]), halt().')
ERL_ROOT=$(erl -noshell -eval \
    'io:format("~s", [code:root_dir()]), halt().')

cat > config.mk <<EOF
# Generated by env.sh — do not edit by hand.
ERTS_VSN     := $ERTS_VSN
ERL_ROOT     := $ERL_ROOT
ERTS_INCLUDE := \$(ERL_ROOT)/erts-\$(ERTS_VSN)/include
EOF

echo "wrote config.mk:"
cat config.mk